        """Make one row of the pattern."""
        result = []

        for c in range(n):
            dist = abs(c - ctr)

            # Direct diagonals always get 2
            if dist == r:
                result.append(2)
            elif dist < r:
                # Inside left side - check layer
                layer = dist + r
                # Place 2 if even layer, 1 if odd (but not on edge)
