# Clean re-implementation

def solve_arc_clean(size=17, center=8):
    """Build grid based on clean understanding."""

    def make_row(r, n=size, ctr=center):
        """Create one row of the diamond wave pattern."""
        result = [0] * n

        # Primary diagonals get 2
        if ctr - r >= 0:
            result[ctr - r] = 2
        if ctr + r < n:
            result[ctr + r] = 2

        # Fill interior based on layer parity
        for c in range(n):
            dist_left = ctr - c
            dist_right = c - ctr

            # Interior means between the two main diagonals
            if dist_left > 0 and dist_right > 0 and dist_left <= r and dist_right <= r:
                layer = dist_left + r
                if layer % 2 == 1 and dist_left < r:
                    result[c] = 1
                elif layer % 2 == 0 and dist_left < r:
                    pass  # already set or remains 0

        return result

    return [make_row(r) for r in range(size)]

# Build submission grid following exact formula derived from analysis
def build_submission():
    center = 8
    size = 17
    grid = [[0]*size for _ in range(size)]

    for r in range(size):
        for c in range(size):
            dist = abs(c - center)

            # Direct diagonal placement
            if dist == r:
                grid[r][c] = 2
            # Right edge mirror  
            elif r <= dist and dist <= 2*center and (dist + r) % 2 == 0:
                grid[r][c] = 2
            # Interior fill with 1 on odd layers
            elif 0 < dist < r and (dist + r) % 2 == 1:
                grid[r][c] = 1

    return grid

